using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using ResolverMaster.Core.Audio;
using UnityEditor;
using UnityEngine;

namespace ResolverMaster.Editor
{
    /// <summary>
    /// ErNa-010/012, the sound files. Effects: generated by Tools/Audio/make_sfx.py into Assets/Audio/Sfx/&lt;file&gt;.wav (the table
    /// event → file is <see cref="AudioCatalog.Sounds"/>). Resolver Master &gt; Audio &gt; Importa suoni rebuilds the
    /// <see cref="SfxLibrary"/> the game reads and copies the music ArtSource/Audio/Music/Music_*.(ogg|mp3|wav) to
    /// Assets/Resources/Audio/Music/ (missing music = silence, no error). ArtSource is only read.
    /// Batch: -executeMethod ResolverMaster.Editor.AudioTools.ImportBatch
    /// </summary>
    public static class AudioTools
    {
        public const string SourceDir = "ArtSource/Audio";
        public const string SfxDir = "Assets/Audio/Sfx";
        public const string MusicDir = "Assets/Resources/Audio/Music";
        public const string LibraryPath = "Assets/Resources/" + SfxLibrary.ResourcesPath + ".asset";
        static readonly string[] MusicExtensions = { ".ogg", ".mp3", ".wav" };
        public static readonly string[] MusicKeys = { AudioCatalog.MusicHome, "Music_Plumber", "Music_TrafficJam", "Music_Penguin" };

        [MenuItem("Resolver Master/Audio/Importa suoni")]
        public static void Import() => Debug.Log(Run());

        public static void ImportBatch()
        {
            try
            {
                Debug.Log(Run());
                EditorApplication.Exit(0);
            }
            catch (Exception e)
            {
                Debug.LogException(e);
                EditorApplication.Exit(1);
            }
        }

        /// <summary>The file of a generated effect.</summary>
        public static string SfxPath(string file) => $"{SfxDir}/{file}.wav";

        static string Run()
        {
            var log = new StringBuilder("AudioTools:\n");
            AssetDatabase.Refresh();
            var missing = RebuildLibrary(log);
            foreach (var key in MusicKeys)
            {
                var src = MusicExtensions.Select(e => Path.Combine(SourceDir, "Music", key + e)).FirstOrDefault(File.Exists);
                if (src == null)
                {
                    log.Append($"  music {key}: missing in {SourceDir}/Music (silence)\n");
                    continue;
                }
                Directory.CreateDirectory(MusicDir);   // only when there is music: no empty folder
                File.Copy(src, Path.Combine(MusicDir, key + Path.GetExtension(src)), true);
                log.Append($"  music {key} <- {src}\n");
            }
            AssetDatabase.Refresh();
            log.Append(missing.Count == 0
                ? "  every event has its sound\n"
                : $"  {missing.Count} file(s) missing (run python Tools/Audio/make_sfx.py): {string.Join(", ", missing)}\n");
            return log.ToString();
        }

        /// <summary>The library of the generated effects, one entry per file of the table. Returns the files not found.</summary>
        public static List<string> RebuildLibrary(StringBuilder log = null)
        {
            var missing = new List<string>();
            var lib = AssetDatabase.LoadAssetAtPath<SfxLibrary>(LibraryPath);
            if (lib == null)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(LibraryPath));
                lib = ScriptableObject.CreateInstance<SfxLibrary>();
                AssetDatabase.CreateAsset(lib, LibraryPath);
            }
            lib.entries.Clear();
            foreach (var file in AudioCatalog.Files().OrderBy(f => f, StringComparer.Ordinal))
            {
                var clip = AssetDatabase.LoadAssetAtPath<AudioClip>(SfxPath(file));
                if (clip == null) missing.Add(file);
                else lib.entries.Add(new SfxLibrary.Entry { name = file, clip = clip });
            }
            EditorUtility.SetDirty(lib);
            AssetDatabase.SaveAssets();
            log?.Append($"  SfxLibrary: {lib.entries.Count} sound(s) for {AudioCatalog.Sounds.Count} events\n");
            return missing;
        }

        public static void RebuildLibraryBatch()
        {
            try
            {
                AssetDatabase.Refresh();
                var missing = RebuildLibrary();
                Debug.Log($"SfxLibrary rebuilt, missing: {missing.Count}");
                EditorApplication.Exit(missing.Count == 0 ? 0 : 3);
            }
            catch (Exception e)
            {
                Debug.LogException(e);
                EditorApplication.Exit(1);
            }
        }
    }

    /// <summary>
    /// ErNa-012: a 16-bit PCM WAV read directly from disk (the generated effects): length, peak, samples at full scale, first and last
    /// sample. Used by the validator (no Unity decoding needed).
    /// </summary>
    public sealed class WavInfo
    {
        public int SampleRate, Channels, Samples;
        public float Peak, First, Last;
        public int FullScaleSamples;
        public float Seconds => SampleRate > 0 ? (float)Samples / SampleRate : 0f;

        /// <summary>Null if the file is not a 16-bit PCM WAV (<paramref name="error"/> says why).</summary>
        public static WavInfo Read(string path, out string error)
        {
            error = null;
            byte[] b;
            try { b = File.ReadAllBytes(path); }
            catch (Exception e)
            {
                error = e.Message;
                return null;
            }
            if (b.Length < 12 || Encoding.ASCII.GetString(b, 0, 4) != "RIFF" || Encoding.ASCII.GetString(b, 8, 4) != "WAVE")
            {
                error = "not a WAV file";
                return null;
            }
            var info = new WavInfo();
            int bits = 0, pos = 12;
            while (pos + 8 <= b.Length)
            {
                string id = Encoding.ASCII.GetString(b, pos, 4);
                int size = BitConverter.ToInt32(b, pos + 4);
                int body = pos + 8;
                if (id == "fmt ")
                {
                    if (BitConverter.ToInt16(b, body) != 1)
                    {
                        error = "not PCM";
                        return null;
                    }
                    info.Channels = BitConverter.ToInt16(b, body + 2);
                    info.SampleRate = BitConverter.ToInt32(b, body + 4);
                    bits = BitConverter.ToInt16(b, body + 14);
                }
                else if (id == "data")
                {
                    if (bits != 16 || info.Channels < 1)
                    {
                        error = "not 16-bit PCM";
                        return null;
                    }
                    int count = Math.Min(size, b.Length - body) / 2;
                    info.Samples = count / info.Channels;
                    for (int i = 0; i < count; i++)
                    {
                        short v = BitConverter.ToInt16(b, body + 2 * i);
                        float f = v / 32768f;
                        float a = Math.Abs(f);
                        if (a > info.Peak) info.Peak = a;
                        if (v >= short.MaxValue || v <= short.MinValue + 1) info.FullScaleSamples++;
                        if (i == 0) info.First = f;
                        if (i == count - 1) info.Last = f;
                    }
                    return info;
                }
                pos = body + size + (size & 1);
            }
            error = "no data";
            return null;
        }
    }

    /// <summary>
    /// ErNa-012: Resolver Master &gt; Audio &gt; Ascolta effetti: every event with its file and pitch, a button to hear it (played as
    /// the game plays it: same pitch, through an AudioSource of a hidden object).
    /// </summary>
    public sealed class SfxListenWindow : EditorWindow
    {
        Vector2 _scroll;
        GameObject _player;
        AudioSource _source;
        string _playing;

        [MenuItem("Resolver Master/Audio/Ascolta effetti")]
        public static void Open() => GetWindow<SfxListenWindow>("Ascolta effetti");

        void OnDisable()
        {
            if (_player != null) DestroyImmediate(_player);
        }

        void Play(string evt)
        {
            if (!AudioCatalog.TryResolve(evt, 1f, out var file, out float pitch)) return;
            var clip = AssetDatabase.LoadAssetAtPath<AudioClip>(AudioTools.SfxPath(file));
            if (clip == null)
            {
                ShowNotification(new GUIContent($"{file}.wav missing: python Tools/Audio/make_sfx.py"));
                return;
            }
            if (_player == null)
            {
                _player = EditorUtility.CreateGameObjectWithHideFlags("SfxListen", HideFlags.HideAndDontSave, typeof(AudioSource));
                _source = _player.GetComponent<AudioSource>();
                _source.playOnAwake = false;
                _source.spatialBlend = 0f;
            }
            _source.Stop();
            _source.clip = clip;
            _source.pitch = pitch;
            _source.volume = 1f;
            _source.Play();
            _playing = evt;
        }

        void OnGUI()
        {
            EditorGUILayout.HelpBox("Effects generated by Tools/Audio/make_sfx.py (Assets/Audio/Sfx). After changing the script: run it, " +
                                    "then Resolver Master > Audio > Importa suoni.", MessageType.Info);
            if (GUILayout.Button("Stop") && _source != null) _source.Stop();
            _scroll = EditorGUILayout.BeginScrollView(_scroll);
            foreach (var kv in AudioCatalog.Sounds)
            {
                EditorGUILayout.BeginHorizontal();
                if (GUILayout.Button("▶", GUILayout.Width(32))) Play(kv.Key);
                var style = kv.Key == _playing ? EditorStyles.boldLabel : EditorStyles.label;
                GUILayout.Label(kv.Key, style, GUILayout.Width(190));
                GUILayout.Label(kv.Value.File + (Mathf.Approximately(kv.Value.Pitch, 1f) ? "" : $"  (pitch {kv.Value.Pitch:0.###})"));
                EditorGUILayout.EndHorizontal();
            }
            EditorGUILayout.EndScrollView();
        }
    }

    /// <summary>
    /// ErNa-010/012: import settings of the sounds for the phone: short effects decompressed on load (no delay when played, Vorbis,
    /// mono), music streamed (Vorbis, stereo kept).
    /// </summary>
    public sealed class AudioImportRules : AssetPostprocessor
    {
        void OnPreprocessAudio()
        {
            var importer = (AudioImporter)assetImporter;
            bool music = assetPath.StartsWith(AudioTools.MusicDir + "/", StringComparison.Ordinal);
            bool sfx = assetPath.StartsWith(AudioTools.SfxDir + "/", StringComparison.Ordinal);
            if (!music && !sfx) return;
            var settings = importer.defaultSampleSettings;
            settings.compressionFormat = AudioCompressionFormat.Vorbis;
            settings.loadType = music ? AudioClipLoadType.Streaming : AudioClipLoadType.DecompressOnLoad;
            settings.quality = music ? 0.5f : 0.7f;
            importer.defaultSampleSettings = settings;
            importer.forceToMono = sfx;
            importer.loadInBackground = music;
        }
    }
}
